mapper.select:
# 选择套餐表的所有,以及将分类表的name命名为categoryName(VO中的属性名)----->进行返回 select s.*,c.name categoryName # 左连接并取别名 from setmeal s left join category c # 在套餐表和分类表的id相等 on s.category_id = c.id
and s.name like concat('%',#{name},'%')
and s.status = #{status}
and s.category_id = #{categoryId}
order by s.create_time desc
